/**
 * @ohos/dsh-ontology/auto-capture — conservative, deterministic candidates.
 *
 * This is deliberately not a second LLM call. It looks for first-person
 * statements that map cleanly onto the closed vocabulary ("我对花生过敏",
 * "我住在上海", "我妈妈叫王芳"). Everything it finds is written as
 * `status='proposed'` and waits in the panel: the model never sees a candidate
 * until the user accepts it.
 *
 * When in doubt, return nothing. A missing candidate costs one manual
 * "remember"; a wrong one costs trust.
 */

/** @typedef {{subject: string, predicate: string, object: string, qualifier?: string}} Candidate */

const STOPWORDS = new Set(["什么", "啥", "谁", "哪", "哪个", "这个", "那个", "你", "他", "她", "它"]);

/**
 * @param {string} value - captured text.
 * @returns {string} cleaned value.
 */
function clean(value) {
	return String(value ?? "")
		.trim()
		.replace(/^[对叫是的了在\s]+/u, "")
		.replace(/[的了吗呢啊呀吧。，,；;！!？?\s]+$/u, "")
		.trim();
}

/**
 * @param {string} value - candidate value.
 * @returns {boolean} whether it is a question/pronoun rather than a fact.
 */
function unusable(value) {
	return value.length === 0 || STOPWORDS.has(value) || value.includes("什么") || value.includes("啥");
}

/**
 * Extract high-confidence candidate facts from one user message.
 * @param {string} text - latest user message.
 * @returns {Candidate[]} candidates in discovery order, deduplicated.
 */
export function extractCandidates(text) {
	const body = String(text ?? "").trim();
	if (body.length === 0) return [];
	/** @type {Candidate[]} */
	const out = [];
	const seen = new Set();
	/** @param {Candidate} candidate - candidate to add. */
	const add = (candidate) => {
		if (unusable(candidate.object)) return;
		const key = `${candidate.subject}|${candidate.predicate}|${candidate.object}|${candidate.qualifier ?? ""}`;
		if (seen.has(key)) return;
		seen.add(key);
		out.push(candidate);
	};

	const name = /(?:我叫|我的名字(?:是|叫))\s*([^\s，。；,;！!？?]{1,16})/u.exec(body);
	if (name !== null) add({ subject: "self", predicate: "name", object: clean(name[1]) });

	const allergy = /我对\s*([^\s，。；,;！!？?]{1,16})\s*过敏/u.exec(body);
	if (allergy !== null) add({ subject: "self", predicate: "allergy", object: clean(allergy[1]) });

	if (/我吃素/u.test(body)) add({ subject: "self", predicate: "diet", object: "素食" });
	if (/我(?:吃|是)清真/u.test(body)) add({ subject: "self", predicate: "diet", object: "清真" });
	const noEat = /我不吃\s*([^\s，。；,;！!？?]{1,10})/u.exec(body);
	if (noEat !== null) add({ subject: "self", predicate: "diet", object: clean(noEat[1]) });

	const city = /我(?:住在|现居|定居在?)\s*([^\s，。；,;！!？?]{2,16})/u.exec(body);
	if (city !== null) add({ subject: "self", predicate: "city", object: clean(city[1]) });

	const language = /我(?:说|用)\s*(中文|英文|英语|日语|韩语|法语|德语|西班牙语)/u.exec(body);
	if (language !== null) add({ subject: "self", predicate: "language", object: clean(language[1]) });

	const birthday = /我(?:的)?生日(?:是|在)?\s*(\d{4}-\d{2}-\d{2}|\d{2}-\d{2})/u.exec(body);
	if (birthday !== null) add({ subject: "self", predicate: "birthday", object: birthday[1] });

	const employer = /我在\s*([^\s，。；,;！!？?]{2,20})\s*(?:工作|上班)/u.exec(body);
	if (employer !== null) add({ subject: "self", predicate: "employer", object: clean(employer[1]) });

	const occupation = /我是(?:一[名个位])?\s*([^\s，。；,;！!？?]{1,12}(?:工程师|产品经理|设计师|老师|医生|律师|会计|程序员))/u.exec(body);
	if (occupation !== null) add({ subject: "self", predicate: "occupation", object: clean(occupation[1]) });

	const relation = /我(妈妈|爸爸|母亲|父亲|老婆|老公|妻子|丈夫|儿子|女儿|哥哥|姐姐|弟弟|妹妹|朋友|同事)(?:叫|是|名叫)\s*([^\s，。；,;！!？?]{1,12})/u.exec(body);
	if (relation !== null) {
		add({ subject: "self", predicate: "relation", object: clean(relation[2]), qualifier: relation[1] });
	}

	const project = /我在做\s*([^\s，。；,;！!？?]{1,20})\s*项目/u.exec(body);
	if (project !== null) add({ subject: "self", predicate: "works_on", object: clean(project[1]) });

	const deadline = /([^\s，。；,;！!？?]{1,20})\s*项目[^\d]{0,10}(?:截止|ddl|deadline)(?:日期)?(?:是|在|为)?\s*(\d{4}-\d{2}-\d{2})/iu.exec(body);
	if (deadline !== null) {
		const subject = clean(deadline[1]).replace(/^我(?:在|的)?/u, "").replace(/项目$/u, "");
		if (!unusable(subject) && subject !== "项目") {
			add({ subject, predicate: "deadline", object: deadline[2] });
		}
	}

	const goal = /我的目标是\s*([^。；\n]{2,40})/u.exec(body);
	if (goal !== null) add({ subject: "self", predicate: "goal", object: clean(goal[1]) });

	return out;
}
